script:
(function () {
  'use strict';
  // Disability income gap, month by month. Each benefit starts after its waiting (elimination)
  // period, counted in 30-day months (90 days = 3 months; a part month pays pro rata), and stops
  // when its benefit period runs out:
  //   share of month m paid = clamp(min(m, start + length) - max(m - 1, start), 0, 1)
  // Employer long-term disability = min(benefit % x monthly income, monthly cap), less tax on it
  // when the employer pays the premiums. Individual policy, short-term disability and other income
  // (a spouse's pay, an SSDI award you expect, etc.) are entered as monthly amounts.
  // Expenses rise once a year by the expense inflation rate. Gap = max(0, expenses - benefits)
  // each month; savings cover the gap until they run out; the rest is unfunded.
  // No Social Security benefit tables are built in - any SSDI amount is your own estimate.
  // CHECKS (Node, scratch tests): $6,000 income, 60% group LTD, 90-day wait, $4,000 expenses,
  // 12 months, no tax, 0% inflation -> months 1-3 gap $4,000 each, months 4-12 benefit $3,600 and
  // gap $400 -> total gap $15,600; 45-day wait -> month 2 paid half ($1,800); benefit period
  // 24 months ends at month 27; 25% tax on the benefit -> $2,700 a month; cap $3,000 -> $3,000;
  // $10,000 savings -> covers $10,000, unfunded $5,600, savings run out in month 3.
  var BENEFIT_TO_65 = -1;

  function share(m, start, length) {
    return Math.max(0, Math.min(1, Math.min(m, start + length) - Math.max(m - 1, start)));
  }

  // p: income, expenses, months, age, inflation, savings,
  //    group {on, pct, cap, days, period, taxRate}, indiv {benefit, days, period},
  //    std {benefit, days, months}, other {benefit, after} (rates as decimals; period in months or BENEFIT_TO_65)
  function periodMonths(period, start, age) {
    return period === BENEFIT_TO_65 ? Math.max(0, (65 - age) * 12 - start) : period;
  }

  function project(p) {
    var gStart = p.group.days / 30, iStart = p.indiv.days / 30, sStart = p.std.days / 30;
    var gLen = periodMonths(p.group.period, gStart, p.age), iLen = periodMonths(p.indiv.period, iStart, p.age);
    var gFull = p.group.on ? Math.min(p.group.pct * p.income, p.group.cap) * (1 - p.group.taxRate) : 0;
    var sav = p.savings, rows = [], tExp = 0, tBen = 0, tGap = 0, unfunded = 0, runOut = 0;
    for (var m = 1; m <= p.months; m++) {
      var exp = p.expenses * Math.pow(1 + p.inflation, Math.floor((m - 1) / 12));
      var g = gFull * share(m, gStart, gLen);
      var ind = p.indiv.benefit * share(m, iStart, iLen);
      var st = p.std.benefit * share(m, sStart, p.std.months);
      var ot = p.other.benefit * share(m, p.other.after, Infinity);
      var ben = g + ind + st + ot;
      var gap = Math.max(0, exp - ben);
      var pay = Math.min(gap, sav);
      sav -= pay;
      if (gap - pay > 0.005 && !runOut) runOut = m;
      tExp += exp; tBen += ben; tGap += gap; unfunded += gap - pay;
      rows.push({ m: m, exp: exp, ben: ben, gap: gap, fromSav: pay, savings: sav });
    }
    return { rows: rows, expenses: tExp, benefits: tBen, gap: tGap, unfunded: unfunded, savingsLeft: sav, runOut: runOut,
             fullMonthly: gFull + p.indiv.benefit + p.other.benefit };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var groupOn = document.getElementById('diGroupOn').checked, taxable = document.getElementById('diTaxable').checked;
    var income = num('diIncome'), expenses = num('diExpenses'), months = Math.round(num('diMonths')), age = Math.round(num('diAge')),
        savings = num('diSavings'), pct = num('diPct'), cap = num('diCap'), gDays = num('diGroupDays'),
        gPeriod = parseInt(document.getElementById('diGroupPeriod').value, 10), taxRate = num('diTaxRate'),
        iBen = num('diIndBenefit'), iDays = num('diIndDays'), iPeriod = parseInt(document.getElementById('diIndPeriod').value, 10),
        sBen = num('diStdBenefit'), sDays = num('diStdDays'), sMonths = num('diStdMonths'),
        oBen = num('diOther'), oAfter = num('diOtherAfter'), inflation = num('diInflation');
    var all = [income, expenses, months, age, savings, pct, cap, gDays, taxRate, iBen, iDays, sBen, sDays, sMonths, oBen, oAfter, inflation];
    var error = document.getElementById('diError');
    var msg = '';
    if (all.some(isNaN) || all.some(function (v) { return v < 0; })) msg = 'Enter non-negative numbers in every field.';
    else if (months < 1 || months > 480) msg = 'Plan for 1 to 480 months of disability.';
    else if (age < 18 || age > 80) msg = 'Enter an age from 18 to 80.';
    else if (pct > 100 || taxRate > 50) msg = 'Enter a benefit of up to 100% of income and a tax rate up to 50%.';
    else if (gDays > 730 || iDays > 730 || sDays > 730) msg = 'Enter waiting periods of up to 730 days.';
    else if (inflation > 20) msg = 'Enter an expense increase of up to 20% a year.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }
    var r = project({ income: income, expenses: expenses, months: months, age: age, inflation: inflation / 100, savings: savings,
                      group: { on: groupOn, pct: pct / 100, cap: cap, days: gDays, period: gPeriod, taxRate: taxable ? taxRate / 100 : 0 },
                      indiv: { benefit: iBen, days: iDays, period: iPeriod },
                      std: { benefit: sBen, days: sDays, months: sMonths },
                      other: { benefit: oBen, after: oAfter } });
    set('diGap', money(r.gap));
    set('diUnfunded', money(r.unfunded));
    set('diBenefits', money(r.benefits));
    set('diExpTotal', money(r.expenses));
    set('diFull', money(r.fullMonthly));
    set('diReplace', income > 0 ? Math.round(r.fullMonthly / income * 100) + '% of your gross income' : '–');
    set('diSavingsNote', savings <= 0 ? 'You have no savings set aside to cover the gap.' :
        (r.runOut ? 'Your savings would run out in month ' + r.runOut + ' of the disability.' :
         'Your savings would cover the whole gap, with ' + money(r.savingsLeft) + ' left.'));
    var gapEl = document.getElementById('diShort');
    gapEl.hidden = !(r.unfunded > 0.5);
    if (r.unfunded > 0.5) gapEl.textContent = 'You would be ' + money(r.unfunded) + ' short over ' + months +
        ' months. More coverage, a shorter waiting period or a larger emergency fund would close the gap.';
    var size = months <= 36 ? 1 : 12;
    set('diPeriodHead', size === 1 ? 'Month' : 'Year');
    var body = document.getElementById('diSchedule');
    body.textContent = '';
    for (var s = 0; s < r.rows.length; s += size) {
      var chunk = r.rows.slice(s, s + size), e = 0, b = 0, g = 0;
      chunk.forEach(function (x) { e += x.exp; b += x.ben; g += x.gap; });
      var tr = document.createElement('tr');
      [String(size === 1 ? s + 1 : s / 12 + 1), money(e), money(b), money(g), money(chunk[chunk.length - 1].savings)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('diForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
